import { index, pgTable, text, timestamp } from "drizzle-orm/pg-core";

import { user } from "./schema";

// Tables ErgStats owns. schema.ts is generated by Better Auth (`pnpm auth:schema`)
// and would lose anything added to it by hand.

/**
 * Reports agents send with the send_feedback MCP tool: something the user asked
 * that the tools couldn't answer, or a tool that failed or misled. Deleted with
 * the account.
 */
export const agentFeedback = pgTable(
  "agent_feedback",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    /** missing_capability, issue or other. */
    type: text("type").notNull(),
    summary: text("summary").notNull(),
    /** The tool the report is about, as the agent named it. */
    tool: text("tool"),
    /** Which app sent it: the OAuth client's host, "registered" for dynamically registered clients, or "api_key". */
    client: text("client"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (table) => [index("agent_feedback_userId_createdAt_idx").on(table.userId, table.createdAt)],
);
